  seat: string;
}

function recommendZone(floor: number, timeIndex: number): number {
  if (timeIndex === 2) return 0;
  if (floor === 3) return 2;
  return 3;
}

function createSnapshot(floor: number, timeIndex: number, zone: number): SeatSnapshot {
  const total = [22, 25, 18][floor - 1] ?? 22;
  const free = Math.max(4, total - 3 - floor * 2 - timeIndex * 4 - zone);
  const light = timeIndex === 0 ? '明亮' : timeIndex === 1 ? '柔和' : '低照度';
  const timeDirection = ['东向晨光', '西侧漫射光', '室内阅读灯'][timeIndex] ?? '均匀天光';
  const zoneDirection = zone === 3 ? '临窗' : zone === 0 ? '北侧' : zone === 2 ? '中庭反射' : '内部均匀';
  const noise = 24 + floor * 2 + timeIndex * 5 + (zone === 1 ? 4 : zone === 2 ? 2 : 0);
  const power = zone === 3 ? 8 : zone === 2 ? 5 : zone === 0 ? 3 : 2;
  const prefix = ['N', 'E', 'C', 'B'][zone] ?? 'N';
  const seat = `${prefix}—${String(7 + floor * 3 + timeIndex * 2).padStart(2, '0')}`;
  return {
    floorLabel: floorLabels[floor - 1] ?? floorLabels[0]!,
    timeLabel: timeLabels[timeIndex] ?? timeLabels[0]!,
    zoneLabel: floorZoneLabels[floor - 1]?.[zone] ?? floorZoneLabels[0]![0]!,
    light,
    lightNote: `${timeDirection} · ${zoneDirection}`,
    noise,
    free,
    total,
    power,
    seat,
  };
}

function setText(selector: string, value: string): void {
  const node = root?.querySelector<HTMLElement>(selector);
  if (node) node.textContent = value;
}

function synchronizeSelection(selectRecommendation = false): void {
  if (!root) return;
  const floorSelect = root.querySelector<HTMLSelectElement>('#floor');
  const timeSelect = root.querySelector<HTMLSelectElement>('#time');
  if (!floorSelect || !timeSelect) return;
  const floor = Number(floorSelect.value);
  const timeIndex = timeSelect.selectedIndex;
  if (selectRecommendation) selectedZone = recommendZone(floor, timeIndex);
  const snapshot = createSnapshot(floor, timeIndex, selectedZone);
  const availability = Math.round((snapshot.free / snapshot.total) * 100);
  const visibleZoneIds = [0, 3, 2];
  root.dataset.selection = `${floor}-${timeIndex}-${selectedZone}`;
  root.dataset.floor = String(floor);
  root.dataset.time = String(timeIndex);
  root.querySelectorAll<HTMLElement>('[data-zone]').forEach((node) => {
    const zone = Number(node.dataset.zone);
    node.classList.toggle('is-active', zone === selectedZone);
    const label = floorZoneLabels[floor - 1]?.[zone];
    if (label) node.textContent = label;
  });
  root.querySelectorAll<HTMLElement>('[data-plan-zone]').forEach((node, index) => {
    const zone = visibleZoneIds[index] ?? 0;
    node.classList.toggle('is-active', zone === selectedZone);
    const label = floorZoneLabels[floor - 1]?.[zone];
    const textNode = node.querySelector<HTMLElement>('b');
    if (label && textNode) textNode.textContent = label;
  });
  scene?.setContext(floor, timeIndex, selectedZone);
  setText('[data-plan-floor]', `日光平面 / ${floor}F · ${snapshot.floorLabel.split(' · ')[1]}`);
  setText('[data-plan-time]', `${snapshot.timeLabel.slice(0, 5)} / ${snapshot.lightNote.split(' · ')[0]}`);
  const caption = root.querySelector<HTMLElement>('[data-plan-caption]');
  if (caption) caption.innerHTML = `<span class="key"></span> 当前建议：${snapshot.floorLabel.split(' · ')[0]} · ${snapshot.zoneLabel}`;
  setText('[data-metric="light"] strong', snapshot.light);
  setText('[data-metric="light"] small', snapshot.lightNote);
  setText('[data-metric="noise"] strong', `${snapshot.noise} dB`);
  setText('[data-metric="noise"] small', `${snapshot.timeLabel} · 演示估算`);
  setText('[data-metric="availability"] strong', `${availability}%`);
  setText('[data-metric="availability"] small', `${snapshot.free} / ${snapshot.total} 席`);
  setText('[data-metric="power"] strong', snapshot.power > 3 ? '充足' : '有限');
  setText('[data-metric="power"] small', `桌侧 ${snapshot.power} 处`);
  setText('[data-stamp-floor]', `${floor}F`);
  setText('[data-stamp-seat]', snapshot.seat);
  setText('[data-stamp-feature]', snapshot.power > 3 ? 'LIGHT / POWER' : 'QUIET / READING');
  setText('[data-reservation-title]', `${snapshot.floorLabel} · ${snapshot.zoneLabel}`);
  const detail = root.querySelector<HTMLElement>('[data-reservation-detail]');
  if (detail) detail.innerHTML = `${snapshot.timeLabel}　建议座位 ${snapshot.seat}<br>${snapshot.light}采光 · ${snapshot.noise} dB · 桌侧插座 ${snapshot.power} 处`;
}

startExperience(defineExperience({
  mount(context): void {
    root = document.createElement('div');
    root.className = 'quiet-library-page';
    root.innerHTML = template();
    context.container.appendChild(root);

    try {
      scene = createLibraryScene(context.canvas, context.quality);
      scene.resize(context.viewport.width, context.viewport.height, context.viewport.dpr);
      synchronizeSelection(true);
    } catch {
      context.canvas.classList.add('canvas-unavailable');
      scene = null;
      synchronizeSelection(true);
    }

    onClick = (event: Event): void => {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const zoneButton = target.closest<HTMLButtonElement>('[data-zone]');
      if (zoneButton) {
        const value = Number(zoneButton.dataset.zone);
        if (Number.isFinite(value)) {
          selectedZone = value;
          synchronizeSelection(false);
        }
      }
      const action = target.closest('.primary-action');
      if (action instanceof HTMLButtonElement) {
        action.textContent = '已保留演示席位 ✓';
        action.classList.add('is-confirmed');
      }
    };
    onChange = (event: Event): void => {
      const target = event.target;
      if (!(target instanceof HTMLSelectElement)) return;
      synchronizeSelection(true);
      root?.classList.add('selection-updated');
      if (updateTimer !== null) window.clearTimeout(updateTimer);
      updateTimer = window.setTimeout(() => root?.classList.remove('selection-updated'), 320);
    };
    root.addEventListener('click', onClick);
    root.addEventListener('change', onChange);
  },
  update(frame): void {
    const state = direct({
      progress: frame.progress,
      elapsed: frame.elapsed,
      pointerX: frame.pointer.x,
      pointerY: frame.pointer.y,
      reducedMotion: frame.reducedMotion,
    });
    scene?.update(state);
    root?.style.setProperty('--story-progress', state.resolve.toFixed(3));
  },
  resize(viewport): void {
    scene?.resize(viewport.width, viewport.height, viewport.dpr);
  },
  dispose(): void {
    if (root && onClick) root.removeEventListener('click', onClick);
    if (root && onChange) root.removeEventListener('change', onChange);
    if (updateTimer !== null) window.clearTimeout(updateTimer);
    updateTimer = null;
    scene?.dispose();
    scene = null;
    root?.remove();
    root = null;
    onClick = null;
    onChange = null;
  },
}));

:root {
  color-scheme: light;
  --paper: #f5f0e5;
  --paper-2: #eae6dc;
  --ink: #24343d;
  --muted: #66767b;
  --line: #aeb7b3;
  --blue: #3f5664;
  --amber: #d39432;
  --amber-soft: #f0d7a3;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  overflow-x: clip;
  color: var(--ink);
  font-family: "Noto Sans SC", "Microsoft YaHei", system-ui, sans-serif;
  background:
    linear-gradient(rgba(76, 94, 98, .035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(76, 94, 98, .035) 1px, transparent 1px),
    radial-gradient(circle at 18% 18%, rgba(255, 255, 255, .9), transparent 34%),
    var(--paper);
  background-size: 42px 42px, 42px 42px, auto, auto;
}

.quiet-library-page { min-height: 100vh; background: transparent; }
canvas.canvas-unavailable { display: none; }
.observatory { position: relative; z-index: 2; width: min(1440px, 100%); margin: 0 auto; padding: 0 clamp(20px, 4vw, 64px); }
.site-header { height: 76px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line); font-size: 12px; letter-spacing: .08em; }
.wordmark { color: inherit; font-weight: 760; text-decoration: none; }
.wordmark span { margin-left: 12px; color: var(--muted); font-weight: 400; }
.site-header nav { display: flex; gap: 28px; }
.site-header nav a { color: inherit; text-decoration: none; border-bottom: 1px solid transparent; }
.site-header nav a:hover, .site-header nav a:focus-visible { border-color: currentColor; }

.hero { position: relative; min-height: min(824px, calc(100vh - 76px)); display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(280px, .55fr); align-items: center; gap: 8vw; padding: 7vh 0 8vh; }
.hero::before { content: ""; position: absolute; left: 51%; top: 12%; bottom: 10%; border-left: 1px solid rgba(73, 91, 95, .18); }
.hero-copy { max-width: 690px; }
.eyebrow { margin: 0 0 18px; color: var(--blue); font-size: 11px; font-weight: 760; letter-spacing: .2em; text-transform: uppercase; }
.hero h1 { margin: 0; font-family: Georgia, "Noto Serif SC", serif; font-size: clamp(52px, 6.2vw, 88px); font-weight: 500; line-height: .98; letter-spacing: -.055em; }
.dek { max-width: 520px; margin: 30px 0 26px; color: #526268; font-size: clamp(15px, 1.25vw, 18px); line-height: 1.85; }
.text-link { display: inline-flex; align-items: center; gap: 34px; padding: 8px 0; border-bottom: 1px solid var(--ink); color: inherit; font-size: 13px; text-decoration: none; }
.library-card { justify-self: end; width: min(100%, 360px); min-height: 380px; padding: 30px; display: flex; flex-direction: column; border: 1px solid #c7c1b5; background: rgba(235, 231, 220, .88); box-shadow: 12px 14px 0 rgba(84, 101, 105, .06); transform: rotate(.65deg); }
.card-index { padding-bottom: 18px; border-bottom: 1px solid var(--line); color: var(--muted); font: 10px ui-monospace, monospace; letter-spacing: .12em; }
.library-card strong { margin: 40px 0; font: 500 28px/1.4 Georgia, "Noto Serif SC", serif; }
.library-card dl { margin: auto 0 20px; }
.library-card dl div { display: flex; justify-content: space-between; padding: 9px 0; border-top: 1px solid #c9c2b4; font-size: 12px; }
.library-card dt, .library-card p { color: var(--muted); }
.library-card p { font-size: 10px; line-height: 1.6; }

.workbench { position: relative; min-height: 112vh; display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(330px, .72fr); gap: 4.5vw; padding: 7vh 0 11vh; border-top: 1px solid var(--line); }
.workbench::before { content: "ARCHITECTURAL OBSERVATION / DEMO"; position: absolute; top: 16px; right: 0; color: rgba(63, 86, 100, .58); font: 9px ui-monospace, monospace; letter-spacing: .16em; }
.plan-panel { position: relative; min-height: 700px; }
.plan-heading { position: relative; z-index: 3; display: flex; justify-content: space-between; align-items: start; }
.plan-heading h2 { margin: 0; font: 500 clamp(30px, 3.2vw, 48px)/1.1 Georgia, "Noto Serif SC", serif; }
.plan-coordinate { min-width: 125px; display: grid; justify-items: end; gap: 10px; color: var(--muted); font: 9px ui-monospace, monospace; letter-spacing: .09em; }
.north { color: var(--ink); font-size: 11px; }
.plan-index { position: absolute; z-index: 3; left: 0; right: 4%; bottom: 72px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; margin: 0; padding: 0; list-style: none; pointer-events: none; }
.plan-index li { display: grid; grid-template-columns: 28px 1fr; gap: 8px; align-items: baseline; padding-top: 8px; border-top: 1px solid rgba(83, 104, 114, .35); color: var(--muted); font-size: 10px; transition: color .24s ease, border-color .24s ease; }
