.control-card { position: relative; z-index: 4; align-self: center; padding: 0 0 24px; border-top: 3px solid var(--blue); border-bottom: 1px solid var(--line); background: rgba(245, 240, 229, .92); backdrop-filter: blur(4px); }
.control-intro { display: grid; gap: 8px; padding: 18px 4px 16px; border-bottom: 1px solid var(--line); }
.control-intro span { color: var(--muted); font: 9px ui-monospace, monospace; letter-spacing: .14em; }
.control-intro b { max-width: 290px; font: 500 14px/1.55 Georgia, "Noto Serif SC", serif; }
.control-row { display: grid; grid-template-columns: 72px 1fr; align-items: center; padding: 15px 4px; border-bottom: 1px solid var(--line); }
.control-row label { color: var(--muted); font-size: 12px; }
select { appearance: none; width: 100%; padding: 5px 26px 5px 0; border: 0; color: var(--ink); background: transparent; background-image: linear-gradient(45deg, transparent 50%, var(--ink) 50%), linear-gradient(135deg, var(--ink) 50%, transparent 50%); background-position: calc(100% - 10px) 50%, calc(100% - 5px) 50%; background-repeat: no-repeat; background-size: 5px 5px; font: 600 15px inherit; }
select:focus-visible, button:focus-visible, a:focus-visible { outline: 2px solid var(--amber); outline-offset: 4px; }
.metrics { display: grid; grid-template-columns: 1fr 1fr; border-bottom: 1px solid var(--line); }
.metrics article { min-height: 98px; padding: 18px 4px; border-bottom: 1px solid #d4d0c7; }
.metrics article:nth-child(odd) { border-right: 1px solid #d4d0c7; }
.metrics span, .metrics small { display: block; color: var(--muted); font-size: 10px; }
.metrics strong { display: block; margin: 7px 0; font: 500 23px Georgia, serif; }
.control-card fieldset { margin: 22px 0 0; padding: 0; border: 0; }
.control-card legend { margin-bottom: 12px; color: var(--muted); font-size: 11px; }
.zone-options { display: flex; flex-wrap: wrap; gap: 8px; }
.zone-options button { padding: 9px 12px; border: 1px solid var(--line); color: inherit; background: transparent; cursor: pointer; font: 12px inherit; }
.zone-options button:hover { border-color: var(--blue); }
.zone-options button.is-active { border-color: var(--amber); background: var(--amber-soft); }
.demo-note { margin: 22px 0 0; color: #97611b; font: 10px ui-monospace, monospace; }
.selection-updated .control-card { box-shadow: 0 0 0 5px rgba(211, 148, 50, .12); }

.resolution { position: relative; min-height: 78vh; display: grid; grid-template-columns: .7fr 1.1fr; align-items: center; gap: 9vw; padding: 10vh 5vw; border-top: 1px solid var(--line); }
.resolution::before { content: ""; position: absolute; inset: 9% 0 10%; pointer-events: none; background: linear-gradient(90deg, transparent 49.9%, rgba(63, 86, 100, .11) 50%, transparent 50.1%), linear-gradient(rgba(63, 86, 100, .07) 1px, transparent 1px); background-size: 100% 100%, 100% 44px; }
.seat-stamp { position: relative; width: clamp(220px, 26vw, 350px); aspect-ratio: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; border: 1px solid var(--blue); border-radius: 50%; color: var(--blue); background: radial-gradient(circle, transparent 45%, rgba(63, 86, 100, .04) 46%); transform: rotate(calc(-7deg + var(--story-progress, 0) * 5deg)); }
.seat-stamp::before, .seat-stamp::after { content: ""; position: absolute; border: 1px solid rgba(63, 86, 100, .32); border-radius: 50%; }
.seat-stamp::before { inset: 9px; }
.seat-stamp::after { inset: 21px; border-style: dashed; }
.seat-stamp span, .seat-stamp i { font: 11px ui-monospace, monospace; letter-spacing: .18em; }
.seat-stamp b { margin: 8px 0; font: 500 clamp(42px, 6vw, 78px) Georgia, serif; }
.resolution-copy { position: relative; max-width: 610px; }
.resolution h2 { margin: 0 0 24px; font: 500 clamp(36px, 4.5vw, 64px)/1.13 Georgia, "Noto Serif SC", serif; }
.resolution-copy > p:not(.eyebrow) { color: #526267; line-height: 1.9; }
.primary-action { min-width: 220px; margin: 28px 0 14px; padding: 17px 22px; display: flex; justify-content: space-between; border: 0; color: var(--paper); background: var(--ink); cursor: pointer; font: 600 15px inherit; }
.primary-action.is-confirmed { background: #516b5d; }
.resolution small { display: block; color: var(--muted); font-size: 10px; }
footer { height: 95px; display: flex; align-items: center; justify-content: space-between; border-top: 1px solid var(--line); color: var(--muted); font-size: 10px; letter-spacing: .08em; }

@media (max-width: 760px) {
  .observatory { padding: 0 20px; }
  .site-header { height: 66px; }
  .wordmark span, .site-header nav a:first-child { display: none; }
  .site-header nav { gap: 14px; }
  .hero { min-height: calc(100vh - 66px); grid-template-columns: 1fr; align-content: start; gap: 24px; padding: 7vh 0 6vh; }
  .hero::before { display: none; }
  .hero-copy { max-width: 100%; }
  .hero h1 { font-size: clamp(44px, 14vw, 60px); line-height: 1.02; }
  .dek { margin: 22px 0 18px; line-height: 1.65; }
  .library-card { justify-self: start; width: 100%; min-height: 210px; padding: 20px; transform: none; }
  .library-card strong { margin: 19px 0; font-size: 21px; }
  .library-card dl { margin: 0; }
  .workbench { min-height: 1280px; display: block; padding: 58px 0 80px; }
