  .plan-heading h2 { max-width: 230px; font-size: 34px; }
  .plan-coordinate { min-width: 92px; }
  .plan-index { right: 0; bottom: 56px; grid-template-columns: 1fr; gap: 7px; }
  .plan-index li { grid-template-columns: 24px 1fr; padding-top: 5px; background: rgba(245, 240, 229, .68); }
